function gems_h($value) {
    return htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8');
}

function gems_query_args($overrides = array()) {
    $args = array(
        'q' => isset($_GET['q']) ? trim((string)$_GET['q']) : '',
        'style' => isset($_GET['style']) ? trim((string)$_GET['style']) : '',
        'slot' => isset($_GET['slot']) ? trim((string)$_GET['slot']) : '',
        'best' => isset($_GET['best']) ? trim((string)$_GET['best']) : '',
        'page' => isset($_GET['page']) ? (int)$_GET['page'] : 1,
    );

    foreach ($overrides as $key => $value) {
        $args[$key] = $value;
    }

    return array_filter($args, function ($value) {
        return $value !== '' && $value !== null;
    });
}
