$query = isset($_GET['q']) ? trim((string)$_GET['q']) : '';
$styleFilter = isset($_GET['style']) ? trim((string)$_GET['style']) : '';
$slotFilter = isset($_GET['slot']) ? trim((string)$_GET['slot']) : '';
$bestFilter = isset($_GET['best']) ? trim((string)$_GET['best']) : '';
$page = isset($_GET['page']) ? max(1, (int)$_GET['page']) : 1;

$styles = array();
$slots = array();
$bestOptions = array();
$ornamentCount = 0;

foreach ($gemsStaticData as $card) {
    $styles[$card['style']] = true;
    foreach ($card['slots'] as $slot) {
        $slots[$slot] = true;
    }
    foreach ($card['best_for'] as $best) {
        $bestOptions[$best] = true;
    }
    $ornamentCount += count($card['ornaments']);
}

$styles = array_keys($styles);
$slots = array_keys($slots);
$bestOptions = array_keys($bestOptions);
sort($styles, SORT_NATURAL | SORT_FLAG_CASE);
sort($slots, SORT_NATURAL | SORT_FLAG_CASE);
sort($bestOptions, SORT_NATURAL | SORT_FLAG_CASE);

$filteredCards = array_values(array_filter($gemsStaticData, function ($card) use ($query, $styleFilter, $slotFilter, $bestFilter) {
    $searchParts = array($card['family_name'], $card['display_name'], $card['style'], (string)$card['item_id']);
    $searchParts = array_merge($searchParts, $card['slots'], $card['best_for']);

    foreach ($card['summary'] as $line) {
        $searchParts[] = strip_tags($line);
    }
    foreach ($card['ornaments'] as $ornament) {
        $searchParts[] = $ornament['name'] . ' ' . $ornament['unlock'];
    }
    foreach ($card['tiers'] as $tier) {
        $searchParts[] = $tier['name'] . ' ' . strip_tags($tier['effect_html']) . ' ' . $tier['upgrade'] . ' ' . $tier['ornament'];
    }

    $haystack = strtolower(implode(' ', $searchParts));
    if ($query !== '' && stripos($haystack, strtolower($query)) === false) {
        return false;
    }
    if ($styleFilter !== '' && strcasecmp($card['style'], $styleFilter) !== 0) {
        return false;
    }
    if ($slotFilter !== '' && !in_array($slotFilter, $card['slots'], true)) {
        return false;
    }
    if ($bestFilter !== '' && !in_array($bestFilter, $card['best_for'], true)) {
        return false;
    }
    return true;
}));

$perPage = 12;
$totalResults = count($filteredCards);
$totalPages = max(1, (int)ceil($totalResults / $perPage));
$page = min($page, $totalPages);
$pagedCards = array_slice($filteredCards, ($page - 1) * $perPage, $perPage);
?>
