                <select class="gems-select" name="style"><option value="">All styles</option><?php foreach ($styles as $styleOption) { ?><option value="<?php echo gems_h($styleOption); ?>"<?php echo strcasecmp($styleOption, $styleFilter) === 0 ? ' selected' : ''; ?>><?php echo gems_h($styleOption); ?></option><?php } ?></select>
                <select class="gems-select" name="slot"><option value="">All slots</option><?php foreach ($slots as $slotOption) { ?><option value="<?php echo gems_h($slotOption); ?>"<?php echo strcasecmp($slotOption, $slotFilter) === 0 ? ' selected' : ''; ?>><?php echo gems_h($slotOption); ?></option><?php } ?></select>
                <select class="gems-select" name="best"><option value="">All best for</option><?php foreach ($bestOptions as $bestOption) { ?><option value="<?php echo gems_h($bestOption); ?>"<?php echo strcasecmp($bestOption, $bestFilter) === 0 ? ' selected' : ''; ?>><?php echo gems_h($bestOption); ?></option><?php } ?></select>
                <button class="gems-search-button" type="submit">Search</button>
            </form>
            <div class="gems-meta-strip">
                <span class="gems-pill"><?php echo count($gemsStaticData); ?> gems indexed</span>
                <span class="gems-pill"><?php echo $ornamentCount; ?> ornament unlocks</span>
                <span class="gems-pill"><?php echo count($pagedCards); ?> shown on this page</span>
                <span class="gems-pill"><?php echo $totalResults; ?> total results</span>
                <span class="gems-pill">Page <?php echo $page; ?> / <?php echo $totalPages; ?></span><br>
				<i style="color:black">Gems are looted from any Monster or Boss in game</i>
            </div>
        </div>
        <div class="gems-results">
            <?php if (empty($pagedCards)) { ?><div class="gems-empty">No gems matched your current search.</div><?php } ?>
            <?php foreach ($pagedCards as $card) { ?>
                <?php $itemImage = ($card['item_id'] > 0 && file_exists(__DIR__ . '/items/' . $card['item_id'] . '.png')) ? 'items/' . $card['item_id'] . '.png' : ''; ?>
                <article class="gems-card">
                    <div class="gems-card-head">
                        <div class="gems-card-figure"><?php if ($itemImage !== '') { ?><img src="<?php echo gems_h($itemImage); ?>" alt="<?php echo gems_h($card['family_name']); ?>" loading="lazy"><?php } else { ?><span class="gems-pill">No image</span><?php } ?></div>
                        <div>
                            <h3 class="gems-card-title"><?php echo gems_h($card['family_name']); ?></h3>
                            <div class="gems-card-subtitle">Base tier: <?php echo gems_h($card['display_name']); ?><?php if ($card['item_id'] > 0) { ?> • Item ID: <?php echo (int)$card['item_id']; ?><?php } ?> • Style: <?php echo gems_h($card['style']); ?></div>
                            <div class="gems-summary"><?php foreach ($card['summary'] as $line) { ?><p><?php echo $line; ?></p><?php } ?></div>
                            <div class="gems-tags"><?php foreach ($card['slots'] as $slot) { ?><span class="gems-tag"><?php echo gems_h($slot); ?></span><?php } ?><?php foreach ($card['best_for'] as $best) { ?><span class="gems-tag"><?php echo gems_h($best); ?></span><?php } ?></div>
                        </div>
                    </div>
                    <div class="gems-sections">
                        <div class="gems-section-box">
                            <h4 class="gems-section-title">Base bonuses</h4>
                            <?php if (empty($card['base_bonuses'])) { ?><div class="gems-empty">No base bonus listed.</div><?php } else { ?><div class="gems-bonus-list"><?php foreach ($card['base_bonuses'] as $bonus) { ?><div class="gems-bonus-item"><div><div class="gems-bonus-label"><?php echo gems_h($bonus['label']); ?></div><span class="gems-bonus-value"><?php echo gems_h($bonus['value']); ?></span></div></div><?php } ?></div><?php } ?>
                        </div>
                        <div class="gems-section-box">
                            <h4 class="gems-section-title">Ornaments</h4>
                            <?php if (empty($card['ornaments'])) { ?><div class="gems-empty">No ornament unlock listed for this gem.</div><?php } else { ?><div class="gems-ornament-grid"><?php foreach ($card['ornaments'] as $ornament) { ?><div class="gems-ornament-item"><div class="gems-ornament-icon"><?php if ($ornament['image'] !== '') { ?><img src="<?php echo gems_h($ornament['image']); ?>" alt="<?php echo gems_h($ornament['name']); ?>" loading="lazy"><?php } else { ?><span class="gems-pill">?</span><?php } ?></div><div><div class="gems-ornament-name"><?php echo gems_h($ornament['name']); ?></div><span class="gems-ornament-note"><?php echo gems_h($ornament['unlock']); ?></span></div></div><?php } ?></div><?php } ?>
                        </div>
                    </div>
                    <details class="gems-tier-details"<?php echo ($query !== '' || count($pagedCards) === 1) ? ' open' : ''; ?>>
                        <summary class="gems-tier-summary"><span>Tier details</span><span><?php echo count($card['tiers']); ?> tiers</span></summary>
                        <div class="gems-tier-table-wrap">
                            <table class="gems-tier-table">
                                <thead><tr><th>Tier</th><th>Name</th><th>Effect / damage / numbers</th><th>Bonuses</th><th>Upgrade</th><th>Ornament</th></tr></thead>
                                <tbody>
                                    <?php foreach ($card['tiers'] as $tier) { ?>
                                        <tr>
                                            <td><strong><?php echo gems_h($tier['tier']); ?></strong></td>
                                            <td><strong><?php echo gems_h($tier['name']); ?></strong></td>
                                            <td><?php echo $tier['effect_html']; ?></td>
                                            <td><?php if (empty($tier['bonuses'])) { ?>&mdash;<?php } else { ?><div class="gems-inline-bonuses"><?php foreach ($tier['bonuses'] as $bonus) { ?><span class="gems-inline-bonus"><strong><?php echo gems_h($bonus['label']); ?></strong> <span><?php echo gems_h($bonus['value']); ?></span></span><?php } ?></div><?php } ?></td>
                                            <td><?php echo gems_h($tier['upgrade']); ?></td>
                                            <td><?php if ($tier['ornament_image'] !== '') { ?><div class="gems-inline-bonuses"><span class="gems-inline-bonus"><img src="<?php echo gems_h($tier['ornament_image']); ?>" alt="<?php echo gems_h($tier['ornament']); ?>" width="20" height="20"> <span><?php echo gems_h($tier['ornament']); ?></span></span></div><?php } else { ?><?php echo gems_h($tier['ornament']); ?><?php } ?></td>
                                        </tr>
                                    <?php } ?>
                                </tbody>
                            </table>
                        </div>
                    </details>
                </article>
            <?php } ?>
        </div>
        <?php if ($totalPages > 1) { ?>
            <div class="gems-pagination">
                <?php if ($page > 1) { ?><a class="gems-page-link" href="gems.php?<?php echo http_build_query(gems_query_args(array('page' => $page - 1))); ?>">&laquo; Prev</a><?php } ?>
                <?php for ($pageNumber = max(1, $page - 2); $pageNumber <= min($totalPages, $page + 2); $pageNumber++) { if ($pageNumber === $page) { echo '<span class="gems-page-current">' . $pageNumber . '</span>'; continue; } echo '<a class="gems-page-link" href="gems.php?' . http_build_query(gems_query_args(array('page' => $pageNumber))) . '">' . $pageNumber . '</a>'; } ?>
                <?php if ($page < $totalPages) { ?><a class="gems-page-link" href="gems.php?<?php echo http_build_query(gems_query_args(array('page' => $page + 1))); ?>">Next &raquo;</a><?php } ?>
            </div>
        <?php } ?>
                </div>
            </div>
        </div>
    </div>
</div>
<?php include 'layout/overall/footer.php'; ?>
